/* Prototype 8：iPadOSはMacintoshを名乗る場合があるため、タッチ点数も併用 */
(function(){
  const isIPad=/iPad/.test(navigator.userAgent)||(/Macintosh/.test(navigator.userAgent)&&navigator.maxTouchPoints>1);
  if(!isIPad)return;
  document.body.classList.add("ipad-mode");
  let raf=0;
  const setAppHeight=()=>{
    cancelAnimationFrame(raf);
    raf=requestAnimationFrame(()=>{
      const vv=window.visualViewport;
      const candidates=[window.innerHeight,document.documentElement.clientHeight];
      if(vv&&vv.height)candidates.push(vv.height);
      const valid=candidates.filter(v=>Number.isFinite(v)&&v>0);
      /* iPad全画面では最大値を使うと、実際の表示領域より高くなることがある。 */
      const h=vv&&vv.height ? vv.height : Math.min(...valid);
      document.documentElement.style.setProperty("--app-height",`${Math.floor(h)}px`);
    });
  };
  window.__setTangramAppHeight=setAppHeight;
  setAppHeight();
  window.addEventListener("resize",setAppHeight,{passive:true});
  window.addEventListener("orientationchange",()=>setTimeout(setAppHeight,120),{passive:true});
  window.visualViewport?.addEventListener("resize",setAppHeight,{passive:true});
  window.visualViewport?.addEventListener("scroll",setAppHeight,{passive:true});
  document.addEventListener("touchmove",e=>{
    if(!e.target.closest(".modal-panel")&&!e.target.closest("button,select"))e.preventDefault();
  },{passive:false});
})();

